const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(weekStart.getDate() - 7);

const validateGitHubToken = async (token, repoFull) => {
  const [owner, repo] = repoFull.split('/');
  const res = await fetch(`https://api.github.com/repos/${owner}/${repo}`, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
    },
  });
  const body = await res.json().catch(() => ({}));
  if (res.status === 401 || res.status === 403) {
    throw new Error('GITHUB_TOKEN is invalid or lacks required permissions.');
  }
  if (!res.ok) {
    throw new Error(`GitHub token validation failed: ${res.status} ${body.message || res.statusText || ''}`.trim());
  }
  if (!body || typeof body.full_name !== 'string') {
    throw new Error('GITHUB_TOKEN validation failed: unexpected GitHub response.');
  }
  return body.full_name;
};

const repoFull = ($env.GITHUB_REPO || '').trim();
if (!/^[a-zA-Z0-9._-]+\/[a-zA-Z0-9._-]+$/.test(repoFull)) {
  throw new Error('Set GITHUB_REPO to owner/repo with GitHub-safe characters only.');
}
const [owner, repo] = repoFull.split('/');

const githubToken = ($env.GITHUB_TOKEN || '').trim();
if (!githubToken) throw new Error('Set GITHUB_TOKEN with repo read access.');
await validateGitHubToken(githubToken, repoFull);
if (!($env.ANTHROPIC_API_KEY || '').trim()) throw new Error('Set ANTHROPIC_API_KEY.');

const language = (($env.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';
const deliveryChannel = (($env.DELIVERY_CHANNEL || '').trim().toLowerCase());
const discordUrl = ($env.DISCORD_WEBHOOK_URL || '').trim();
const slackUrl = ($env.SLACK_WEBHOOK_URL || '').trim();
const emailFromRaw = ($env.SUMMARY_EMAIL_FROM || '').trim();
const emailFrom = emailFromRaw || 'n8n@localhost';
const emailTo = ($env.SUMMARY_EMAIL_TO || '').trim();

let channel = deliveryChannel;
if (!channel) {
  if (discordUrl) channel = 'discord';
  else if (slackUrl) channel = 'slack';
  else if (emailTo) channel = 'email';
}

if (!['discord', 'slack', 'email'].includes(channel)) {
  throw new Error('Set DELIVERY_CHANNEL to discord, slack, or email (and the matching destination variable).');
}
if (channel === 'discord' && !discordUrl) throw new Error('DELIVERY_CHANNEL=discord requires DISCORD_WEBHOOK_URL.');
if (channel === 'slack' && !slackUrl) throw new Error('DELIVERY_CHANNEL=slack requires SLACK_WEBHOOK_URL.');
if (channel === 'email' && !emailTo) throw new Error('DELIVERY_CHANNEL=email requires SUMMARY_EMAIL_TO.');
if (channel === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailTo)) throw new Error('SUMMARY_EMAIL_TO must be a valid email address.');
if (channel === 'email' && emailFromRaw && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailFromRaw)) throw new Error('SUMMARY_EMAIL_FROM must be a valid email address.');

return [{
  json: {
    owner,
    repo,
    repoFullName: `${owner}/${repo}`,
    language,
    weekStart: weekStart.toISOString(),
    weekEnd: now.toISOString(),
    deliveryChannel: channel,
    emailFrom: emailFrom,
    emailTo: emailTo
  }
}];

const isGitHubError = (row) => (
  row && typeof row === 'object' && !Array.isArray(row) &&
  typeof row.message === 'string' && typeof row.documentation_url === 'string'
);

const fetchGitHubPages = async (baseUrl, query = {}) => {
  const token = ($env.GITHUB_TOKEN || '').trim();
  if (!token) throw new Error('Set GITHUB_TOKEN with repo read access.');
  const headers = {
    Authorization: `Bearer ${token}`,
    Accept: 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
  };
  const records = [];
  let page = 1;
  while (page <= 50) {
    const params = new URLSearchParams({ ...query, per_page: '100', page: String(page) });
    const res = await fetch(`${baseUrl}?${params}`, { headers });
    const body = await res.json().catch(() => ({}));
    if (!res.ok) {
      throw new Error(`GitHub ${baseUrl} failed: ${res.status} ${body.message || res.statusText || ''}`.trim());
    }
    if (isGitHubError(body)) throw new Error(body.message);
    const batch = Array.isArray(body) ? body : (Array.isArray(body.items) ? body.items : []);
    records.push(...batch.filter((row) => !isGitHubError(row)));
    if (batch.length < 100) break;
    page += 1;
  }
  return records;
};
const config = $('Load Config').first().json;
const records = await fetchGitHubPages(
