const config = $('Load Config').first().json;
const records = await fetchGitHubPages(
  'https://api.github.com/search/issues',
  { q: `repo:${config.repoFullName} is:pr is:merged merged:>=${config.weekStart.slice(0, 10)}`, sort: 'updated' },
);
return [{ json: { records } }];

const config = $('Load Config').first().json;
const weekStart = new Date(config.weekStart);
const weekEnd = new Date(config.weekEnd);

const inWeek = (iso) => {
  if (!iso) return false;
  const d = new Date(iso);
  return d >= weekStart && d <= weekEnd;
};

const isGitHubError = (row) => (
  row && typeof row === 'object' && !Array.isArray(row) &&
  typeof row.message === 'string' && typeof row.documentation_url === 'string'
);

const collectRecords = (nodeName) => {
  const item = $(nodeName).first()?.json;
  if (!item) throw new Error(`Missing output from ${nodeName}`);
  if (item.error) throw new Error(String(item.error));
  const rows = item.records;
  if (!Array.isArray(rows)) return [];
  return rows.filter((row) => row && typeof row === 'object' && !Array.isArray(row) && !isGitHubError(row));
};

const commits = collectRecords('Fetch Commits')
  .filter((c) => inWeek(c.commit?.author?.date || c.commit?.committer?.date))
  .map((c) => ({
    sha: (c.sha || '').slice(0, 7),
    message: c.commit?.message?.split('\n')[0] || '',
    author: c.author?.login || c.commit?.author?.name || 'unknown',
    date: c.commit?.author?.date || c.commit?.committer?.date
  }));

const issues = collectRecords('Fetch Closed Issues')
  .filter((i) => !i.pull_request && inWeek(i.closed_at))
  .map((i) => ({ number: i.number, title: i.title, closedAt: i.closed_at }));

const prs = collectRecords('Fetch Merged PRs')
  .filter((p) => p.merged_at && inWeek(p.merged_at))
  .map((p) => ({ number: p.number, title: p.title, author: p.user?.login || 'unknown', mergedAt: p.merged_at }));

const contributors = new Set(commits.map((c) => c.author));

const instruction = config.language === 'FR'
  ? 'Rédigez un résumé narratif hebdomadaire en français. Structurez avec: Points forts, Commits, Issues résolues, PRs fusionnées, et TL;DR.'
  : 'Write a weekly narrative dev summary in English. Structure with: Highlights, Commits, Issues Resolved, Pull Requests Merged, and TL;DR.';

const systemPrompt = config.language === 'FR'
  ? 'Vous résumez l\'activité de développement GitHub pour les équipes d\'ingénierie. Soyez précis et n\'inventez pas de travail absent des données fournies.'
  : 'You summarize GitHub development activity for engineering teams. Be accurate and do not invent work that is not present in the input data.';

const activity = {
  repository: config.repoFullName,
  weekStart: config.weekStart,
  weekEnd: config.weekEnd,
  commits,
  closedIssues: issues,
  mergedPullRequests: prs
};

return [{
  json: {
    config,
    stats: {
      commits: commits.length,
      issues: issues.length,
      prs: prs.length,
      contributors: contributors.size
    },
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 2048,
      temperature: 0.3,
      system: systemPrompt,
      messages: [{
        role: 'user',
        content: `${instruction}\n\nRepository activity JSON:\n${JSON.stringify(activity, null, 2)}`
      }]
    }
  }
}];

const built = $('Build Claude Prompt').first().json;
const config = built.config;
const stats = built.stats;
const statsLine = `${stats.commits} commits · ${stats.issues} issues closed · ${stats.prs} PRs merged · ${stats.contributors} contributors`;

const apiError = $json.error?.message || $json.message || ($json.error ? String($json.error) : '');
const summary = apiError
  ? `Claude API unavailable (${apiError}). Stats for the week: ${statsLine}.`
  : (($json.content || []).map(part => part.text || '').join('\n').trim() || 'No summary generated.');

const title = `Weekly Dev Summary — ${config.repoFullName}`;
const period = `${config.weekStart.slice(0, 10)} → ${config.weekEnd.slice(0, 10)}`;
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

return [{
  json: {
    config,
    title,
    period,
    statsLine,
    summary,
    markdown: `# ${title}\n*${period}*\n\n> ${statsLine}\n\n${summary}`,
    discordBody: {
      content: `**${title}**\n*${period}*\n${statsLine}\n\n${summary.slice(0, 1800)}`
    },
    slackBody: {
      blocks: [
        { type: 'header', text: { type: 'plain_text', text: title } },
        { type: 'section', text: { type: 'mrkdwn', text: `*${period}*\n${statsLine}` } },
        { type: 'section', text: { type: 'mrkdwn', text: summary.slice(0, 2800) } }
      ]
    },
    emailSubject: `${title} (${period})`,
    emailText: `${title}\n${period}\n${statsLine}\n\n${summary}`,
    emailHtml: `<h1>${escapeHtml(title)}</h1><p><em>${escapeHtml(period)}</em></p><p>${escapeHtml(statsLine)}</p><pre style="white-space:pre-wrap;font-family:inherit">${escapeHtml(summary)}</pre>`
  }
}];
